input.new_string:
words = text.split(" ")
last_index = len(words) - 1
result = []
for index, word in enumerate(words):
    if any(char.isupper() for char in word[1:]):
        result.append(word)
        continue

    is_first = index == 0 or words[index - 1].endswith(":")
    is_last = index == last_index or word.endswith(":")

    if word.rstrip(_TRAILING_PUNCTUATION).lower() in SMALL_WORDS and not (is_first or is_last):
        result.append(word.lower())
    else:
        result.append(word[:1].upper() + word[1:])
return " ".join(result)
